e represent the action of $\tilde\sigma_i$ on the core blocks in terms of matrices $R_i$ as follows:

\begin{equation}
\label{rep_rho}
\varphi^P_{\phi_1,\phi_2,\phi_3,\phi_4}{(\widetilde{w})} \mapsto \sum_{Q}(R_i)_{PQ}\, \varphi^Q_{\tilde\sigma_i(\phi_1,\phi_2,\phi_3,\phi_4)}({\tilde\sigma_i \widetilde{w}}),
\end{equation}

where the action of the $\tilde\sigma_i$ on $\widetilde{w}$ is determined (in part) by their action on the $z_i$, and the action on the labels $\varphi_1,\dots,\varphi_4$ (hence the sectors $M_1,\dots, M_4$) is by the induced permutation. Explicitly, one has
\begin{gather*}
\tilde\sigma_i(\varphi_1,\varphi_2,\varphi_3,\varphi_4) = \begin{cases} (\varphi_2,\varphi_1,\varphi_3,\varphi_4) &\text{for } i=1, \\(\varphi_1,\varphi_3,\varphi_2,\varphi_4) &\text{for } i=2,\\ ( \varphi_1,\varphi_2,\varphi_4,\varphi_3) &\text{for } i=3 \end{cases}
\end{gather*}
and
\begin{gather}
(R_1)_{PQ} = \delta_{PQ} \operatorname{e}\biggl(\frac{\mu_{12}}{2}\biggr) B_{M_1^* M_2^*}\begin{bmatrix} M_1&M_2\\ {\mathcal{V}}&P\end{bmatrix}\!(+),\nonumber\\
(R_2)_{PQ} = \operatorname{e}\biggl(\frac{\mu_{23}}{2}\biggr) B_{PQ}\begin{bmatrix} M_2&M_3\\ M_1^*&M_4\end{bmatrix}\!(+),\nonumber\\
(R_3)_{PQ} = \delta_{PQ} \operatorname{e}\biggl(\frac{\mu_{34}}{2}\biggr) B_{M_4 M_3}\begin{bmatrix} M_3&M_4\\ P&{\mathcal{V}}\end{bmatrix}\!(+),\label{eq:corerep}
\end{gather}
where the phases arise from the factors of $z_{ij}$ on the right-hand side of~\eqref{def:coreblock4point}.
Moreover,
using equations~\eqref{eq:B}, one sees that $R_1$ and $R_3$ are given simply by
\begin{gather}
\label{eq:sg}
(R_1)_{PQ} = \delta_{PQ} \zeta^{M_1^*}_{M_2,P}\operatorname{e}\biggl(\frac{h}{6}-\frac{h_P}{2}\biggr),\qquad
(R_3)_{PQ} = \delta_{PQ} \xi^P_{M_3,M_4}\operatorname{e}\biggl(\frac{h}{6}-\frac{h_P}{2}\biggr),
\end{gather}
where $h$ is as in~\eqref{eq:muij}, and \smash{$\xi_{M_iM_j}^{M_k}$} and \smash{$\zeta_{M_iM_j}^{M_k}$} are the phases defined in~\eqref{def:xi}--\eqref{def:zeta} and satisfying~\eqref{ord2zetaxi}.

We need to verify that the following five relations, which follow from~\eqref{GammaPres}, are satisfied
\begin{gather*}
(1)\quad R_{1} R_{3} = R_{3} R_{1} ,\\
(2)\quad R_{1} R_{2} R_{1} = R_{2} R_{1} R_{2} ,\\
(3)\quad R_{2} R_{3} R_{2} = R_{3} R_{2} R_{3} ,\\
(4)\quad R_{1} R_{2} R_{3}^2R_{2} R_{1} = I ,\\
(5)\quad (R_{1} R_{2} R_{3})^4 = I .
\end{gather*}
The proof of relations (1)--(3) is straightforward since it has been shown in~\cite{Moore:1989vd}
 that the braiding matrices provide a representation of ${\rm Br}_4$, whose generators satisfy relations analogous to \mbox{(1)--(3)}, as we see in~\eqref{def:br4}. Therefore, all we need to check is that the extra phases, present due to the fact that we are considering the action on the core blocks and not the chiral blocks, are the same on both sides of the equations. Indeed, in relation (1) the right- and left-hand sides have an identical phase factor of $\operatorname{e}\bigl(\tfrac{\mu_{12}+\mu_{34} }{2}\bigr)= \operatorname{e}(-h/6)$, so (1) holds. Likewise, the left- and right-hand side of $(2)$ have an identical phase factor given by \smash{$\operatorname{e}\bigl(\tfrac{\mu_{12}+\mu_{23}+\mu_{13}}{2}\bigr)$}, and that of $(3)$ is given~by~\smash{$\operatorname{e}\bigl(\tfrac{\mu_{23}+\mu_{34}+\mu_{24}}{2}\bigr)$}.

To prove (4), we use~\eqref{eq:corerep} and~\eqref{eq:sg} to write
\begin{gather*}
\bigl(R_{1} R_{2} R_{3}^2R_{2} R_{1}\bigr)_{PQ}=\sum_{R}\zeta_{M_2,P}^{M_1^*}\bigl(\xi_{M_1,M_4}^R\xi_{M_4,M_1}^R\bigr) \zeta_{M_1,Q}^{M_2^*}\operatorname{e}\biggl(h_2+h_4-\frac{h_P}{2}-h_R-\frac{h_Q}{2}\biggr) \nonumber\\
\hphantom{\bigl(R_{1} R_{2} R_{3}^2R_{2} R_{1}\bigr)_{PQ}=\sum_{R}}{}
\times B_{PR}\begin{bmatrix}M_1&M_3\\M_2^*&M_4\end{bmatrix}\!(+) B_{RQ}\begin{bmatrix}M_3&M_1\\M_2^*&M_4\end{bmatrix}\!(+),
\end{gather*}
which leads to (4) upon plugging in~\eqref{ord2zetaxi} and~\eqref{eq:BB}.
Finally, to show that (5) holds we begin by noting that the following relation holds:
\begin{gather*}
(4')\quad R_3R_2R_1^2R_2R_3=I,
\end{gather*}
the derivation is identical to that of (4). We now make repeated use of relations (1)--(4) and ($4'$) as well as $R_{1}^2=R_3^2$, which follows trivially from equations~\eqref{eq:sg}, to show that
\begin{align*}
(R_1R_2R_3)^4&{}
=(R_1R_2R_1R_3R_2R_3)^2
=(R_2R_1R_2R_3R_2R_3)^2 \\
&{}=R_2R_1R_3R_2R_3R_3R_2R_1R_2R_3R_2R_3
=R_2R_3\bigl(R_1R_2R_3^2R_2R_1\bigr)R_2R_3R_2R_3 \\
&{}=(R_2R_3)^3
=R_3R_2R_3R_3R_2R_3
=R_3R_2R_1^2R_2R_3
=I,
\end{align*}
and therefore relation (5) holds as well.

The OPE coefficients~\eqref{def:cA} satisfy
\begin{gather*}
{\mathcal{A}}_{1234} =(\rho_T)^{-1} {\mathcal{A}}_{1243} \tilde \rho_{ T} = (\rho_S)^{-1} {\mathcal{A}}_{1423} \tilde \rho_{S},
\end{gather*}
where $\rho_T$ and $\rho_S$ are as given in~\eqref{eq:tpq} and~\eqref{eq:spq} and similarly for $\tilde \rho$.

\label{cor_corecor}The core correlator satisfies
\begin{gather*}
{F}_{\phi^1,\phi^2,\phi^3,\phi^4}(\tau,\bar\tau)={F}_{\phi^1,\phi^2,\phi^3,\phi^4}\biggl(\frac{a\tau+b}{c\tau+d},{\frac{\overline{a\tau+b}}{\overline{c\tau+d}}}\biggr)
\end{gather*}
for all \smash{$\bigl(\begin{smallmatrix}a& b\\ c&d \end{smallmatrix}\bigr)\in \Gamma(2)$}. Moreover, the above holds for all \smash{$\bigl(\begin{smallmatrix}a& b\\ c&d \end{smallmatrix}\bigr)\in {\rm SL}_2({\mathbb Z})$} if $\phi_2=\phi_3=\phi_4$.
